import {cms} from '@/cms'
import {HomePage} from '@/schema'

export default async function Page() {
  const home = await cms.get({type: HomePage})
  return <h1>{home.title}</h1>
}

import {cms} from '@/cms'
import {BlogPost} from '@/schema'

// All matches, as an array (possibly empty)
const posts = await cms.find({type: BlogPost})

// The first match, or null
const latest = await cms.first({
  type: BlogPost,
  orderBy: {desc: BlogPost.publishDate}
})

// The first match, or throws "Entry not found"
const post = await cms.get({type: BlogPost, path: 'hello-world'})

// The number of matches
const total = await cms.count({type: BlogPost})

import {cms} from '@/cms'
import {BlogPost} from '@/schema'
import {Query} from 'alinea'

const cards = await cms.find({
  type: BlogPost,
  select: {
    title: Query.title,
    url: Query.url,
    date: BlogPost.publishDate,
    cover: BlogPost.cover
  }
})
// Array<{title: string, url: string, date: string, cover: ImageLink | null}>

// A single expression returns plain values
const urls = await cms.find({type: BlogPost, select: Query.url})
// Array<string>

import {cms} from '@/cms'
import {BlogPost} from '@/schema'
import {Query} from 'alinea'

const posts = await cms.find({
  type: BlogPost,
  select: {
    // Built-in properties of the entry
    id: Query.id,
    title: Query.title,
    url: Query.url,
    // Fields of the BlogPost type
    intro: BlogPost.intro,
    cover: BlogPost.cover
  }
})
// Array<{id: string, title: string, url: string, intro: string, cover: ImageLink | null}>

import {cms} from '@/cms'
import {Config, Field, Query} from 'alinea'

export const Page = Config.document('Page', {
  fields: {
    seo: Field.object('SEO', {
      fields: {
        title: Field.text('SEO title'),
        description: Field.text('SEO description')
      }
    })
  }
})

const pages = await cms.find({
  type: Page,
  select: {url: Query.url, title: Page.seo.title},
  orderBy: {asc: Page.seo.title}
})
// Array<{url: string, title: string}>

import {Config, Field} from 'alinea'

export const Author = Config.document('Author', {
  fields: {
    avatar: Field.image('Avatar'),
    bio: Field.text('Bio', {multiline: true})
  }
})

export const Category = Config.document('Category', {fields: {}})

export const Blog = Config.document('Blog', {
  contains: ['BlogPost'],
  fields: {}
})

export const BlogPost = Config.document('Blog post', {
  fields: {
    publishDate: Field.date('Publish date'),
    intro: Field.text('Intro', {multiline: true, searchable: true}),
    featured: Field.check('Featured'),
    cover: Field.image('Cover image'),
    author: Field.entry('Author', {condition: {_type: 'Author'}}),
    categories: Field.entry.multiple('Categories', {
      condition: {_type: 'Category'}
    }),
    tags: Field.select.multiple('Tags', {
      options: {news: 'News', release: 'Release', tutorial: 'Tutorial'}
    }),
    body: Field.richText('Body', {searchable: true})
  }
})
